const base='http://127.0.0.1:3100';
(async()=>{
 const wb=await (await fetch(base+'/api/workbooks/ops-plan')).json(); const rev=wb.revision; delete wb.revision; delete wb.savedAt;
 const payload=(user,address,value)=>({baseRevision:rev,userId:user,workbook:wb,changes:[{sheetId:'plan',address,value}]});
 let r=await fetch(base+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload('riley','F20','one'))}); console.log('save1',r.status,(await r.json()).revision);
 r=await fetch(base+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload('morgan','G20','two'))}); console.log('different-cell merge',r.status,(await r.json()).revision);
 r=await fetch(base+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload('priya','F20','conflict'))}); console.log('same-cell conflict',r.status,await r.json());
 const bad={...payload('riley','H20','bad'),workbook:{...wb,title:'Hacked'}}; r=await fetch(base+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(bad)}); console.log('identity rejection',r.status,(await r.json()).error);
 const hist=await (await fetch(base+'/api/workbooks/ops-plan/history?sheetId=plan&address=F20')).json(); console.log('history',hist.length,hist[0].userName);
})();
